import{_ as e,o as n,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Stamina, recuperación y cadencia de combate","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/stamina-and-reactive-combat.md","filePath":"es/game-design/combat/stamina-and-reactive-combat.md"}'),t={name:"es/game-design/combat/stamina-and-reactive-combat.md"};function r(s,a,c,d,l,p){return n(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="stamina-recovery-and-reactive-combat" tabindex="-1">Stamina, recuperación y cadencia de combate <a class="header-anchor" href="#stamina-recovery-and-reactive-combat" aria-label="Enlace permanente a &quot;Stamina, recuperación y cadencia de combate&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la baseline automática; Propuesto para la ampliación de stamina/fatiga y la dirección de entrada manual; Sin resolver para su compatibilidad. Implementación: tiempos heredados del servidor, sin cambios de entrada o recursos de Batch 03.</strong></p><p><a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a></p><h2 id="automatic-baseline-and-manual-input-conflict" tabindex="-1">Baseline automática y conflicto de entrada manual <a class="header-anchor" href="#automatic-baseline-and-manual-input-conflict" aria-label="Enlace permanente a &quot;Baseline automática y conflicto de entrada manual&quot;">​</a></h2><p>Combat Design v0.2, secciones 2 y 11, preserva los golpes automáticos ordinarios y la interacción avanzada opcional. Preparar intención para un golpe programado no concede un ataque extra. Los golpes opcionales retenidos y listos siguen siendo exploratorios.</p><p>Batch 03 propone una tecla de ataque configurable (Space es un ejemplo, no una asignación aprobada), un intento activado manualmente, animación visible, coste de stamina/fatiga, recuperación y tiempos específicos del arma. Busca tiempos, posicionamiento y ejecución del jugador significativos. <strong>Hacer obligatoria la entrada manual para cada ataque entraría en conflicto con la baseline automática con estado Aceptado.</strong> La fuente no establece si sería un modo opcional o un reemplazo.</p><p><strong>Decisión histórica pendiente de Batch 03, aclarada abajo por Batch 05:</strong> quedaron dos decisiones abiertas: explorar interacción manual/retenida opcional conservando el combate automático, o revisar explícitamente la baseline aprobada antes de evaluar un reemplazo. Batch 03 no seleccionó ninguna opción. El reemplazo en conflicto no está implementado ni se eleva a Aceptado. La entrada opcional sigue necesitando un contrato técnico y evaluación de juego; llamarla opcional no significa que su detalle ya esté aprobado.</p><h2 id="proposed-stamina-and-fatigue" tabindex="-1">Stamina y fatiga con estado Propuesto <a class="header-anchor" href="#proposed-stamina-and-fatigue" aria-label="Enlace permanente a &quot;Stamina y fatiga con estado Propuesto&quot;">​</a></h2><p>La stamina es el recurso físico preferido para investigar, sin copiar automáticamente los costes marciales de maná de AOS. Los usos candidatos incluyen compromiso del ataque, recuperación, presión de acciones repetidas, persecución y movimiento, equipo pesado, precisión/control y ritmo táctico. Las acciones sostenidas de alto impacto no deberían ser gratuitas indefinidamente. Si la fatiga se deriva de stamina o se representa por separado sigue Sin resolver.</p><p>Aquí no se fija ningún coste de ataque, curva de regeneración, penalización de agotamiento ni duración de recuperación. Fallos, intentos cancelados, objetivos no válidos, entradas repetidas y acciones fallidas necesitan reglas explícitas de cobro antes de implementar. El coste de stamina, la recuperación, el cooldown, la oportunidad de ataque y la duración de animación visual son conceptos distintos.</p><h2 id="responsiveness-and-inheritance-gap" tabindex="-1">Respuesta y diferencias heredadas <a class="header-anchor" href="#responsiveness-and-inheritance-gap" aria-label="Enlace permanente a &quot;Respuesta y diferencias heredadas&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/characters/stats.html">Stats</a> define las funciones acotadas de DEX/STR/INT con estado Propuesto. Una DEX baja no debería hacer que el combate básico se sienta a cámara lenta. Clase de arma, tipo de ataque, postura, recuperación, fatiga, carga y técnica son factores principales propuestos para la cadencia; DEX puede influir de forma acotada en recuperación o precisión. Son objetivos de diseño, no una fórmula nueva.</p><p>Los tiempos de ataque pre-AOS heredados usan stamina actual y velocidad del arma, no DEX directamente; el daño heredado incorpora STR, Tactics y Anatomy. Estas relaciones son diferencias de compatibilidad que reconciliar, no aprobación definitiva de Syrolands. En este batch no se realizó ninguna evaluación nueva de entradas del cliente o animaciones, y no se establece soporte para Space.</p><h2 id="authority-and-presentation" tabindex="-1">Autoridad y presentación <a class="header-anchor" href="#authority-and-presentation" aria-label="Enlace permanente a &quot;Autoridad y presentación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Límite para un diseño futuro</th></tr></thead><tbody><tr><td>INTENCIÓN DEL USUARIO</td><td>Solicitar ataque o región/técnica preferida mediante una entrada reasignable</td></tr><tr><td>ESTADO AUTORITATIVO DEL SERVIDOR</td><td>Validar objetivo, alcance, LOS, tiempos y recursos; resolver impacto, región real, daño, trauma y recuperación</td></tr><tr><td>ESTADO SINCRONIZADO</td><td>Replicar solo resultados aprobados por el servidor e información permitida de oportunidades/evaluación</td></tr><tr><td>PRESENTACIÓN DEL CLIENTE</td><td>Mostrar señales, animación y respuesta; la anticipación nunca concede un impacto ni dicta tiempos</td></tr></tbody></table><p>El juego autoritativo no puede esperar al renderizado o a que termine una animación. Aquí no se selecciona identificador de paquete, condición de capacidades, cola de entradas, política de predicción ni compensación de latencia. Los futuros diseños de interacción deben definir comportamiento compatible y alternativa de respaldo. Accesibilidad/reasignación, equidad ante latencia y resistencia a automatización son requisitos de diseño sin resolver, no justificaciones para hitboxes autoritativas del cliente.</p><h2 id="concentration-pressure" tabindex="-1">Presión sobre Concentration <a class="header-anchor" href="#concentration-pressure" aria-label="Enlace permanente a &quot;Presión sobre Concentration&quot;">​</a></h2><p>Daño, trauma local, movimiento, presión repetida, aturdimiento/impacto y ciertos rasgos de armas son candidatos propuestos para interrumpir o tensionar Concentration mágica. <a href="/Syrolands-Public/es/game-design/magic.html#concentration-under-pressure">Magia define Concentration</a>, su representación y fórmulas sin resolver, incluida la distinción entre <a href="/Syrolands-Public/es/game-design/magic.html#fizzle-versus-interruption">fizzle e interrupción</a>. Esta página no crea una regla nueva de aturdimiento ni declara que todo golpe interrumpa automáticamente.</p><h2 id="related-design" tabindex="-1">Diseño relacionado <a class="header-anchor" href="#related-design" aria-label="Enlace permanente a &quot;Diseño relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado y decisiones sin resolver</a></p><h2 id="spellbook-pressure-—-batch-04" tabindex="-1">Presión al consultar el spellbook — Batch 04 <a class="header-anchor" href="#spellbook-pressure-—-batch-04" aria-label="Enlace permanente a &quot;Presión al consultar el spellbook — Batch 04&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html#physical-reference-under-pressure">Referencia física bajo presión</a> propone navegación del libro y recuerdo antes de lanzar un hechizo conocido no memorizado. Daño, fatiga, movimiento y trauma local pueden presionar Concentration bajo su <a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">definición existente en magia</a>. Esto no selecciona tiempos de lanzamiento/ataque, asignación de tecla ni entrada cuerpo a cuerpo obligatoria, y no resuelve el conflicto automático/manual anterior.</p><h2 id="batch-05-clarification" tabindex="-1">Aclaración de Batch 05 <a class="header-anchor" href="#batch-05-clarification" aria-label="Enlace permanente a &quot;Aclaración de Batch 05&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/legacy-and-modern.html">Combate Legacy y Modern</a> es la terminología actual con estado Propuesto: cadencia automática Legacy frente a inicio activado por el jugador Modern, con selección de objetivo y reglas de recursos/acciones compartidas. Modern es la dirección experimental preferida mientras Legacy sigue como alternativa compatible en la propuesta. Así, Batch 05 no exige que todos abandonen los ataques automáticos; implementación y aceptación formal siguen siendo pasos separados. «Reactive» permanece en nombres históricos de secciones/rutas, no como etiqueta principal de modo.</p><p><a href="/Syrolands-Public/es/game-design/combat/flow.html">Flow</a>, <a href="/Syrolands-Public/es/game-design/combat/actions.html">fases de acción</a> y <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">el registro de variables</a> refinan las preguntas de stamina/cadencia sin elegir fórmulas. La fuente anterior y el alcance experimental con estado Aceptado permanecen intactos.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Alcance numérico de prueba de Batch 06 <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Enlace permanente a &quot;Alcance numérico de prueba de Batch 06&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">perfil de tres armas</a> asigna valores de prueba con estado Experimental a Longsword, Spear y War Hammer. Sus reglas de fases, recursos, cadencia, Flow, Familiarity marcial y preparación solo se aplican a esa prueba futura. Los ejemplos anteriores siguen siendo alternativas históricas fuera de este perfil; de ello no se deriva equilibrio definitivo, implementación de juego ni asignación numérica de hechizos.</p>',27)])])}const b=e(t,[["render",r]]);export{m as __pageData,b as default};
